CREATE OR REPLACE FUNCTION public.force_start_round(p_room_id UUID, p_player_id UUID) RETURNS JSONB AS $$ DECLARE err_ctx text; err_msg text; BEGIN INSERT INTO public.moves (room_id, player_id, action_type, payload) VALUES (p_room_id, p_player_id, 'START_ROUND', '{}'::jsonb); RETURN jsonb_build_object('success', true); EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS err_ctx = PG_EXCEPTION_CONTEXT; GET STACKED DIAGNOSTICS err_msg = MESSAGE; RETURN jsonb_build_object('success', false, 'error', err_msg, 'context', err_ctx); END; $$ LANGUAGE plpgsql SECURITY DEFINER;
